    helper_name = (family.helper_agent_name or "").strip()
    return helper_name or DEFAULT_FAMILY_HELPER_AGENT_NAME


def _get_accessible_family(request: HttpRequest) -> FamilyGroup:
    user = cast(User, request.user)

    if not family_planner_feature_flags.is_enabled(user):
        raise Http404("Family planner is not available.")

    family = get_user_immediate_family(user)
    if family is None:
        raise Http404("Immediate family not found.")

    family = FamilyGroup.objects.select_related("feature_settings").get(id=family.id)
    if not family.feature_settings.agent_enabled:
        raise Http404("Family planner is not enabled for this family.")

    has_permission, error_msg = validate_family_admin_permission(
        user,
        family,
        "access family planner",
    )
    if not has_permission and not user.is_staff:
        raise PermissionDenied(error_msg or "Only family admins can use the planner.")

    return family


def _build_context_payload(request: HttpRequest, family: FamilyGroup) -> dict[str, Any]:
    payload: dict[str, Any] = {
        "source_screen": request.GET.get("source_screen") or "web_clancy",
        "family_id": str(family.id),
    }
    for key in CONTEXT_QUERY_KEYS:
        value = request.GET.get(key)
        if value:
            payload[key] = value
    return payload


@login_required
@require_GET
