  });
  hideThreadList();
}

async function startNewThread() {
  hideThreadList();
  if (state.isSending) {
    return;
  }
  setStatus('Starting new conversation...');
  try {
    const thread = await apiRequest('/api/family-agent/threads/', {
      method: 'POST',
      json: {},
    });
    state.threadId = thread?.id || null;
    clearPolling();
    updateTokenPressureBanner('ok');
    renderEmptyState();
    state.threadsLoaded = false;
    setStatus('');
    input?.focus();
  } catch (error) {
    setStatus(error.message || 'Could not start a new conversation.');
  }
}

function toggleThreadList() {
  if (state.threadsOpen) {
    hideThreadList();
  } else {
    showThreadList();
  }
}

function showThreadList() {
  if (!threadList) {
    return;
  }
  threadList.hidden = false;
  state.threadsOpen = true;
  threadsToggle?.setAttribute('aria-expanded', 'true');
  void loadThreadList();
}

function hideThreadList() {
  if (!threadList) {
    return;
  }
  threadList.hidden = true;
  state.threadsOpen = false;
  threadsToggle?.setAttribute('aria-expanded', 'false');
}

async function loadThreadList() {
  if (!threadList) {
    return;
  }
  if (!state.threadsLoaded) {
    threadList.replaceChildren(buildThreadEmpty('Loading...'));
  }
  try {
    const payload = await apiRequest('/api/family-agent/threads/');
    const items = Array.isArray(payload) ? payload : (payload?.results || []);
    state.threadsLoaded = true;
    renderThreadList(items.slice(0, 5));
  } catch (error) {
    threadList.replaceChildren(buildThreadEmpty(error.message || 'Could not load conversations.'));
  }
}

function renderThreadList(items) {
  if (!threadList) {
    return;
  }
  threadList.replaceChildren();
  if (!items.length) {
    threadList.appendChild(buildThreadEmpty('No recent conversations yet.'));
    return;
  }
  items.forEach((item) => {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'clancy-assistant-thread-item';
    button.dataset.clancyThreadId = item.id;
    button.setAttribute('role', 'option');
    if (item.id === state.threadId) {
      button.classList.add('is-active');
      button.setAttribute('aria-selected', 'true');
    }
    const title = document.createElement('span');
    title.className = 'clancy-assistant-thread-item-title';
    title.textContent = item.title || 'Conversation';
    const meta = document.createElement('span');
    meta.className = 'clancy-assistant-thread-item-meta';
    meta.textContent = formatRelativeTime(item.updated_at || item.created_at);
    button.append(title, meta);
    threadList.appendChild(button);
  });
}

function buildThreadEmpty(text) {
  const node = document.createElement('p');
  node.className = 'clancy-assistant-thread-empty';
  node.textContent = text;
  return node;
}

async function switchToThread(threadId) {
  if (!threadId || threadId === state.threadId) {
    hideThreadList();
    return;
  }
  hideThreadList();
  state.threadId = threadId;
  clearPolling();
  renderEmptyState();
  setStatus('Loading conversation...');
  try {
    await loadMessages();
    setStatus('');
  } catch (error) {
    setStatus(error.message || 'Could not load conversation.');
  }
}

function formatRelativeTime(value) {
  if (!value) {
    return '';
  }
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    return '';
  }
  const diffMs = Date.now() - date.getTime();
  const diffMin = Math.round(diffMs / 60000);
  if (diffMin < 1) {
    return 'just now';
  }
  if (diffMin < 60) {
    return `${diffMin}m ago`;
  }
  const diffHr = Math.round(diffMin / 60);
  if (diffHr < 24) {
    return `${diffHr}h ago`;
  }
  const diffDay = Math.round(diffHr / 24);
  if (diffDay < 7) {
    return `${diffDay}d ago`;
  }
  return date.toLocaleDateString();
}

